import{_ as t,o as a,c as d,ag as o}from"./chunks/framework.B7PviQjB.js";const g=JSON.parse(`{"title":"Markdown reference","description":"The Markdown syntax a note's preview renders, including math, diagrams, and the HTML tags it allows.","frontmatter":{"title":"Markdown reference","description":"The Markdown syntax a note's preview renders, including math, diagrams, and the HTML tags it allows.","type":"reference"},"headers":[],"relativePath":"notes/markdown-reference.md","filePath":"notes/markdown-reference.md"}`),s={name:"notes/markdown-reference.md"};function r(n,e,c,l,i,h){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="markdown-reference" tabindex="-1">Markdown reference <a class="header-anchor" href="#markdown-reference" aria-label="Permalink to &quot;Markdown reference&quot;">​</a></h1><p>The Markdown syntax a note&#39;s preview renders, including math, diagrams, and the HTML tags it allows.</p><p><strong>Conventions.</strong> Notes use GitHub-Flavored Markdown with one difference: a single <code>Enter</code> is a line break. Two lines with no blank line between them render as two lines, not one paragraph. Leave a blank line to start a new paragraph.</p><p>To see the result as you type, switch the note to <strong>Split</strong> at the right of the toolbar.</p><h2 id="text" tabindex="-1">Text <a class="header-anchor" href="#text" aria-label="Permalink to &quot;Text&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To get</th><th>Type</th></tr></thead><tbody><tr><td>Bold</td><td><code>**bold**</code></td></tr><tr><td>Italic</td><td><code>*italic*</code></td></tr><tr><td>Strikethrough</td><td><code>~~struck~~</code></td></tr><tr><td>Inline code</td><td><code>`code`</code></td></tr><tr><td>Link</td><td><code>[text](https://example.com)</code></td></tr><tr><td>Automatic link</td><td><code>https://example.com</code></td></tr><tr><td>Literal character</td><td><code>\\*</code> (backslash before a Markdown character)</td></tr></tbody></table><p>Links to <code>http://</code> and <code>https://</code> addresses open in a new tab.</p><h2 id="headings-and-blocks" tabindex="-1">Headings and blocks <a class="header-anchor" href="#headings-and-blocks" aria-label="Permalink to &quot;Headings and blocks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To get</th><th>Type</th></tr></thead><tbody><tr><td>Heading 1 to 6</td><td><code>#</code> to <code>######</code>, then a space</td></tr><tr><td>Blockquote</td><td><code>&gt; </code> at the start of a line</td></tr><tr><td>Horizontal rule</td><td><code>---</code> on its own line, after a blank line</td></tr><tr><td>Bullet list</td><td><code>- </code>, <code>* </code>, or <code>+ </code></td></tr><tr><td>Numbered list</td><td><code>1. </code></td></tr><tr><td>Nested item</td><td>Indent the item under the one above</td></tr><tr><td>Task</td><td><code>- [ ] </code> (open) or <code>- [x] </code> (done)</td></tr></tbody></table><p>A line with only <code>-</code> under a paragraph stays an empty bullet. It does not turn the line above into a heading.</p><h2 id="tables" tabindex="-1">Tables <a class="header-anchor" href="#tables" aria-label="Permalink to &quot;Tables&quot;">​</a></h2><p>Separate cells with <code>|</code>, and put a row of <code>---</code> under the header row:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>| Name  | Role     |</span></span>\n<span class="line"><span>| ----- | -------- |</span></span>\n<span class="line"><span>| Alice | Designer |</span></span>\n<span class="line"><span>| Bob   | Engineer |</span></span></code></pre></div><p>Add <code>:</code> to the separator to align a column: <code>:---</code> (left), <code>:---:</code> (center), <code>---:</code> (right).</p><h2 id="images" tabindex="-1">Images <a class="header-anchor" href="#images" aria-label="Permalink to &quot;Images&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To get</th><th>Type</th></tr></thead><tbody><tr><td>Image</td><td><code>![Alt text](https://example.com/photo.png)</code></td></tr><tr><td>Image at a set size</td><td><code>&lt;img src=&quot;https://example.com/photo.png&quot; alt=&quot;Photo&quot; width=&quot;400&quot;&gt;</code></td></tr></tbody></table><p>See <a href="#allowed-html">Allowed HTML</a> for the rules on <code>&lt;img&gt;</code>.</p><h2 id="code-blocks" tabindex="-1">Code blocks <a class="header-anchor" href="#code-blocks" aria-label="Permalink to &quot;Code blocks&quot;">​</a></h2><p>Open and close a block with three backticks. Put a language name after the opening fence to highlight it:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>```python</span></span>\n<span class="line"><span>print(&quot;hello&quot;)</span></span>\n<span class="line"><span>```</span></span></code></pre></div><p>The source pane highlights these languages, by name or alias:</p><table tabindex="0"><thead><tr><th>Language</th><th>Names you can use</th></tr></thead><tbody><tr><td>JavaScript</td><td><code>javascript</code>, <code>js</code>, <code>mjs</code>, <code>cjs</code>, <code>node</code>, <code>jsx</code></td></tr><tr><td>TypeScript</td><td><code>typescript</code>, <code>ts</code>, <code>mts</code>, <code>cts</code>, <code>tsx</code></td></tr><tr><td>JSON</td><td><code>json</code>, <code>jsonc</code>, <code>json5</code></td></tr><tr><td>Python</td><td><code>python</code>, <code>py</code></td></tr><tr><td>CSS</td><td><code>css</code></td></tr><tr><td>HTML</td><td><code>html</code>, <code>htm</code>, <code>xml</code>, <code>svg</code></td></tr><tr><td>SQL</td><td><code>sql</code>, <code>postgres</code>, <code>postgresql</code>, <code>mysql</code></td></tr><tr><td>YAML</td><td><code>yaml</code>, <code>yml</code></td></tr><tr><td>Shell</td><td><code>shell</code>, <code>sh</code>, <code>bash</code>, <code>zsh</code>, <code>console</code>, <code>shellsession</code></td></tr><tr><td>Go</td><td><code>go</code>, <code>golang</code></td></tr><tr><td>Rust</td><td><code>rust</code>, <code>rs</code></td></tr><tr><td>C and C++</td><td><code>c</code>, <code>h</code>, <code>cpp</code>, <code>c++</code>, <code>cc</code>, <code>cxx</code>, <code>hpp</code></td></tr><tr><td>Java</td><td><code>java</code></td></tr></tbody></table><p>The preview highlights these and many other common languages. Each code block in the preview has a <strong>Copy</strong> button.</p><h2 id="math" tabindex="-1">Math <a class="header-anchor" href="#math" aria-label="Permalink to &quot;Math&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To get</th><th>Type</th></tr></thead><tbody><tr><td>Inline math</td><td><code>$E = mc^2$</code></td></tr><tr><td>Display math</td><td><code>$$</code> on its own line, the formula, then <code>$$</code> on its own line</td></tr></tbody></table><p>Math uses LaTeX syntax. To show a dollar sign that would otherwise start math, type <code>\\$</code>.</p><h2 id="diagrams" tabindex="-1">Diagrams <a class="header-anchor" href="#diagrams" aria-label="Permalink to &quot;Diagrams&quot;">​</a></h2><p>Use <code>mermaid</code> as the fence language to draw a <a href="https://mermaid.js.org/" target="_blank" rel="noreferrer">Mermaid</a> diagram, such as a flowchart or sequence diagram:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>```mermaid</span></span>\n<span class="line"><span>flowchart LR</span></span>\n<span class="line"><span>  Draft --&gt; Review --&gt; Published</span></span>\n<span class="line"><span>```</span></span></code></pre></div><p>The diagram follows the light or dark theme and redraws as you type. The first diagram in a note can take a moment to appear; until then you see its source.</p><p>When a diagram can&#39;t be drawn, its source stays on screen with a message above it that starts with <code>Diagram error:</code>. These features are refused:</p><table tabindex="0"><thead><tr><th>Not allowed</th><th>Message</th></tr></thead><tbody><tr><td>Image shapes (<code>@{ img: … }</code>)</td><td><code>Diagram error: image shapes are not allowed</code></td></tr><tr><td>Sequence actor icons</td><td><code>Diagram error: actor icons are not allowed</code></td></tr><tr><td><code>url(…)</code> or <code>@import</code> in diagram styles</td><td><code>Diagram error: CSS that loads a URL is not allowed</code></td></tr><tr><td>HTML that loads a URL</td><td><code>Diagram error: HTML that loads a URL is not allowed</code></td></tr><tr><td>A diagram over 50,000 characters</td><td><code>Diagram error: source is longer than 50000 characters</code></td></tr></tbody></table><p>These are ignored without a message:</p><ul><li><code>%%{init: …}%%</code> directives and front matter inside the fence, including <code>title:</code></li><li>Bold, italic, and other HTML formatting in labels. <code>&lt;br/&gt;</code> still breaks a line.</li></ul><h2 id="allowed-html" tabindex="-1">Allowed HTML <a class="header-anchor" href="#allowed-html" aria-label="Permalink to &quot;Allowed HTML&quot;">​</a></h2><p>The preview shows other HTML as plain text. These two tags are the exceptions.</p><table tabindex="0"><thead><tr><th>Tag</th><th>Rules</th></tr></thead><tbody><tr><td><code>&lt;details&gt;</code> and <code>&lt;summary&gt;</code></td><td>Put each tag on its own line. Keep the summary on one line. Use <code>&lt;details open&gt;</code> to start expanded. The body between the tags is ordinary Markdown, so lists, code blocks, and nested foldouts work.</td></tr><tr><td><code>&lt;img&gt;</code></td><td>Only <code>src</code>, <code>alt</code>, <code>width</code>, and <code>height</code>. Width and height must be a whole number or a percentage, such as <code>400</code> or <code>50%</code>.</td></tr></tbody></table><p>A foldout looks like this:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;details&gt;</span></span>\n<span class="line"><span>&lt;summary&gt;Meeting notes&lt;/summary&gt;</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>- Alice: ship the beta</span></span>\n<span class="line"><span>- Bob: update the docs</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>&lt;/details&gt;</span></span></code></pre></div><p>An <code>&lt;img&gt;</code> tag with any other attribute, or a value like <code>width=&quot;400px&quot;</code>, shows as plain text in the preview.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/notes/write-and-format.html">Write and format</a> to apply most of this from the toolbar.</li><li><a href="/docs/notes/keyboard-shortcuts.html">Keyboard shortcuts</a> for formatting keys.</li><li><a href="/docs/notes/">Notes</a> for an overview of the editor.</li></ul>',42)])])}const m=t(s,[["render",r]]);export{g as __pageData,m as default};
